def binary_search(arr, target):
    # 在有序数组中二分查找 target，返回下标，不存在返回 -1
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
# 时间复杂度：每次区间减半，为 O(log n)，空间复杂度 O(1)
# 边界条件：空数组时 right = -1，循环不执行，正确返回 -1

def f(a):
    n=len(a)
    for i in range(n):
        for j in range(n-1):
            if a[j]>a[j+1]:
                a[j],a[j+1]=a[j+1],a[j]
    return a

class Solution:
    def twoSum(self, nums, target):
        seen = {}
        for i, v in enumerate(nums):
            if target - v in seen:
                return [seen[target - v], i]
            seen[v] = i
        return []
# 时间复杂度 O(n)，哈希查找平均 O(1)
